<?php require '../config.php';require_admin();$adminPage=true;$pageTitle='Quản lý liên hệ';if(isset($_GET['delete'])){$st=$pdo->prepare('DELETE FROM contacts WHERE contact_id=?');$st->execute([(int)$_GET['delete']]);header('Location: contacts.php?deleted=1');exit;}$contacts=$pdo->query('SELECT * FROM contacts ORDER BY created_at DESC')->fetchAll();require '../includes/header.php';?><div class="row g-4"><div class="col-md-3"><?php require 'nav.php';?></div><div class="col-md-9"><h1 class="section-title">Thông tin liên hệ</h1><?php if(isset($_GET['deleted'])): ?><div class="alert alert-success">Đã xóa liên hệ.</div><?php endif; ?><div class="content-card table-responsive"><table class="table"><thead><tr><th>Người gửi</th><th>Email</th><th>Tiêu đề</th><th>Nội dung</th><th>Ngày gửi</th><th></th></tr></thead><tbody><?php foreach($contacts as $c): ?><tr><td><?= e($c['full_name']) ?></td><td><?= e($c['email']) ?></td><td><?= e($c['subject']) ?></td><td><?= e($c['message']) ?></td><td><?= e($c['created_at']) ?></td><td><a class="btn btn-sm btn-outline-danger" href="?delete=<?= $c['contact_id'] ?>" onclick="return confirm('Xóa nội dung liên hệ?')">Xóa</a></td></tr><?php endforeach; ?></tbody></table><?php if(!$contacts): ?><p>Chưa có liên hệ nào.</p><?php endif; ?></div></div></div><?php require '../includes/footer.php';?>
